void sensor_temp_update( SInt16 temp_val )
{
	if(temp_val< (-40<<8))
		temp_val = (-40<<8);	   // less tha -40C will be read as -40C
	
	//update the temperature print val
	if(temp_val < 0)
		last_temp_read = (temp_val | 0xffff0000);
	else
		last_temp_read = temp_val;
	
	
  set_temp_sensor_present(TRUE);		// set the temp sensor is present
	set_temp_sensor_value((temp_val + (40<<8) + 0x80)>>8);
}
